/** Shape of data/appearance/catalog.json (generated by tools/import-lpc.ts). */

export type Material = 'body' | 'hair' | 'cloth';

/** How a layer is recolored: body/hair follow the player's choice; cloth uses a fixed palette. */
export interface Recolor {
  material: Material;
  palette?: string;
}

export interface LayerRef {
  /** Path under public/, e.g. "assets/lpc/characters/body/bodies/male/walk.png". */
  sheet: string;
  zIndex: number;
  recolor?: Recolor;
}

export interface Opt {
  id: string;
  labelKey: string;
}

export interface ColorOpt extends Opt {
  swatch: string;
}

/** A 6-color ramp: `base` is what the sheets are drawn in; `colors` are the targets. */
export interface PaletteSet {
  base: string[];
  colors: Record<string, string[]>;
}

export interface AppearanceCatalog {
  palettes: Record<Material, PaletteSet>;
  bodies: Opt[];
  skins: ColorOpt[];
  hairStyles: Opt[];
  hairColors: ColorOpt[];
  layers: {
    body: Record<string, LayerRef[]>;
    hair: Record<string, LayerRef>;
    outfit: Record<string, Record<string, LayerRef[]>>;
  };
  tileset: string;
}
